body.script:
//

/* ────────────────────────────────────────────
   UTILITIES
   ──────────────────────────────────────────── */
const $ = (s) => document.querySelector(s);
const $$ = (s) => document.querySelectorAll(s);

/* Create XHTML-namespaced elements (required inside SVG foreignObject).
   Standard createElement produces null-namespace nodes whose CSS is ignored. */
const XHTML_NS = 'http://www.w3.org/1999/xhtml';
function createEl(tag) { return document.createElementNS(XHTML_NS, tag); }

/* Set innerHTML via DOMParser so child nodes get the XHTML namespace.
   createContextualFragment requires an in-DOM node, so we use DOMParser instead. */
function setHTML(el, html) {
  while (el.firstChild) el.removeChild(el.firstChild);
  if (!html) return;
  try {
    const doc = new DOMParser().parseFromString(
      '<div xmlns="http://www.w3.org/1999/xhtml">' + html + '</div>',
      'application/xhtml+xml'
    );
    const root = doc.documentElement;
    while (root.firstChild) el.appendChild(document.adoptNode(root.firstChild));
  } catch(e) {
    /* Fallback for content that isn't strict XHTML (e.g. entities) */
    el.textContent = html.replace(/<[^>]+>/g, '');
  }
}

const botArea   = $('#botArea');
const msgs      = $('#msgs');
const chatInput = $('#chatInput');
const ctxArea   = $('#ctxArea');
const plusMenu  = $('#plusMenu');
const simCursor = $('#simCursor');

/* Cancellable wait */
let runId = 0;
let paused = false;
let _resolve = null;

function wait(ms) {
  return new Promise((resolve) => {
    const check = () => {
      if (paused) { _resolve = check; return; }
      resolve();
    };
    setTimeout(check, ms);
  });
}

/* Safe guard for cancelled scenes */
function alive(rid) { return runId === rid; }

/* ────────────────────────────────────────────
   MESSAGE HELPERS
   ──────────────────────────────────────────── */
function thinkingDots() {
  return '<div class="dots"><span></span><span></span><span></span></div>';
}

function addMessage(role, html, extraClass) {
  const el = createEl('div');
  el.className = 'msg ' + role + (extraClass ? ' ' + extraClass : '');
  setHTML(el, html);
  msgs.appendChild(el);
  requestAnimationFrame(() => {
    el.classList.add('vis');
    msgs.scrollTop = msgs.scrollHeight;
  });
  return el;
}

function clearMessages() {
  while (msgs.firstChild) msgs.removeChild(msgs.firstChild);
}

/* Type text into the input field, character by character */
async function typeIntoInput(text, speed, rid) {
  chatInput.value = '';
  for (let i = 0; i < text.length; i++) {
    if (!alive(rid)) return;
    chatInput.value = text.substring(0, i + 1);
    await wait(speed || 35);
  }
}

function clearInput() { chatInput.value = ''; chatInput.placeholder = 'Nachricht eingeben…'; }

/* ────────────────────────────────────────────
   CONTEXT TAG HELPERS
   ──────────────────────────────────────────── */
function setContext(label, type) {
  while (ctxArea.firstChild) ctxArea.removeChild(ctxArea.firstChild);
  if (!label) return;
  const tag = createEl('div');
  tag.className = 'ctx-tag' + (type ? ' ' + type : '');
  setHTML(tag, '<button class="x-btn">×</button><span>' + label + '</span>');
  ctxArea.appendChild(tag);
  requestAnimationFrame(() => tag.classList.add('vis'));
}

function clearContext() { while (ctxArea.firstChild) ctxArea.removeChild(ctxArea.firstChild); }

/* ────────────────────────────────────────────
   PLUS MENU
   ──────────────────────────────────────────── */
function showPlusMenu() { plusMenu.classList.add('visible'); }
function hidePlusMenu() { plusMenu.classList.remove('visible'); }

/* ────────────────────────────────────────────
   DRAWERS / OVERLAYS
   ──────────────────────────────────────────── */
function openDrawer(id)  { $(id).classList.add('open'); }
function closeDrawer(id) { $(id).classList.remove('open'); }

function showPromptPicker() { $('#promptPicker').classList.add('visible'); }
function hidePromptPicker() { $('#promptPicker').classList.remove('visible'); }

/* ────────────────────────────────────────────
   HEADER MENU
   ──────────────────────────────────────────── */
function showHeaderMenu() { $('#headerMenu').classList.add('visible'); }
function hideHeaderMenu() { $('#headerMenu').classList.remove('visible'); }

/* ────────────────────────────────────────────
   CMS PAGE CONTENT
   ──────────────────────────────────────────── */
const cmsDE = {
  title: 'Lorem Ipsum Dolor Sit Amet',
  desc: 'Consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.',
  heading: 'Ut Enim Ad Minim Veniam',
  text: 'Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident.',
  tags: ['Lorem', 'Ipsum', 'Dolor', 'Amet'],
  bc: 'Home'
};
const cmsEN = {
  title: 'Sed Ut Perspiciatis Unde Omnis',
  desc: 'Nemo enim ipsam voluptatem quia voluptas sit aspernatur aut odit aut fugit.',
  heading: 'Quis Autem Vel Eum Iure',
  text: 'At vero eos et accusamus et iusto odio dignissimos ducimus qui blanditiis praesentium voluptatum deleniti atque corrupti quos dolores et quas molestias.',
  tags: ['Sed', 'Perspiciatis', 'Omnis', 'Iste'],
  bc: 'Home'
};

function setCMS(data) {
  $('#cmsTitle').textContent = data.title;
  $('#cmsDesc').textContent = data.desc;
  $('#cmsHeading').textContent = data.heading;
  $('#cmsText').textContent = data.text;
  const tagsEl = $('#cmsTags');
  while (tagsEl.firstChild) tagsEl.removeChild(tagsEl.firstChild);
  data.tags.forEach(t => {
    const s = createEl('span');
    s.className = 'volto-tag';
    s.textContent = t;
    tagsEl.appendChild(s);
  });
  $('#bcTitle').textContent = data.bc;
}

function flashElement(el) {
  el.classList.add('flash');
  setTimeout(() => el.classList.remove('flash'), 1200);
}

function setLang(lang) {
  if (lang === 'en') {
    $('#langDe').classList.remove('active');
    $('#langEn').classList.add('active');
  } else {
    $('#langEn').classList.remove('active');
    $('#langDe').classList.add('active');
  }
}

/* ────────────────────────────────────────────
   CURSOR SIMULATION
   ──────────────────────────────────────────── */
function showCursor(x, y) {
  simCursor.style.left = x + 'px';
  simCursor.style.top = y + 'px';
  simCursor.classList.add('vis');
}
function moveCursor(x, y) {
  simCursor.style.left = x + 'px';
  simCursor.style.top = y + 'px';
}
function hideCursor() { simCursor.classList.remove('vis'); }

/* Simulate text selection highlight */
function selectText(el, start, end) {
  const text = el.textContent;
  setHTML(el, text.substring(0, start) +
    '<span class="v-selected">' + text.substring(start, end) + '</span>' +
    text.substring(end));
}
function clearSelection(el) {
  el.textContent = el.textContent;
}

/* ────────────────────────────────────────────
   RESET
   ──────────────────────────────────────────── */
function resetAll() {
  botArea.className = 'bot-area';
  clearMessages();
  clearInput();
  clearContext();
  hidePlusMenu();
  hideHeaderMenu();
  hidePromptPicker();
  closeDrawer('#historyDrawer');
  closeDrawer('#settingsDrawer');
  closeDrawer('#glossaryDrawer');
  closeDrawer('#tagDrawer');
  closeDrawer('#promptsDrawer');
  closeDrawer('#permDrawer');
  hideCursor();
  setCMS(cmsDE);
  setLang('de');
  $('#transOverlay').classList.remove('visible');
  $('#pmEdit').classList.remove('active-item');
  $('#pmEdit').querySelector('span').textContent = 'Bearbeiten';
}

/* ════════════════════════════════════════════
   SCENES
   ════════════════════════════════════════════ */
const scenes = [
  { name: 'Launcher',            fn: sceneLauncher },
  { name: 'Willkommen',          fn: sceneWelcome },
  { name: 'Chat',                fn: sceneChat },
  { name: 'Funktionsmenü',       fn: scenePlusMenu },
  { name: 'Übersetzen',          fn: sceneTranslation },
  { name: 'Textoptimierung',     fn: sceneTextOptimize },
  { name: 'Bearbeiten-Modus',    fn: sceneEditMode },
  { name: 'Layout-Agent',        fn: sceneLayoutAgent },
  { name: 'Prompt-Picker',       fn: scenePromptPicker },
  { name: 'Header-Menü',         fn: sceneHeaderMenu },
  { name: 'Einstellungen',       fn: sceneSettings },
  { name: 'Glossar',             fn: sceneGlossary },
  { name: 'Tag-Zuordnungen',     fn: sceneTagMappings },
  { name: 'Prompt-Verwaltung',   fn: scenePromptsPanel },
  { name: 'Berechtigungen',      fn: scenePermissions },
  { name: 'Verlauf',             fn: sceneHistory },
  { name: 'Sync',                fn: sceneSync },
  { name: 'Schließen',           fn: sceneClose },
];

let curScene = 0;

/* ── Scene 0: Launcher ── */
async function sceneLauncher(rid) {
  botArea.classList.add('show-launcher', 'launcher-pulse');
  await wait(2500);
}

/* ── Scene 1: Welcome ── */
async function sceneWelcome(rid) {
  botArea.classList.remove('launcher-pulse');
  botArea.classList.add('show-panel');
  await wait(600); if (!alive(rid)) return;
  addMessage('bot', 'Hallo! 👋 Ich bin der <strong>Volto AI Assistant</strong>. Wie kann ich dir helfen?');
  await wait(3000);
}

/* ── Scene 2: Normal conversation with citations ── */
async function sceneChat(rid) {
  await typeIntoInput('Fasse diese Seite zusammen', 30, rid);
  if (!alive(rid)) return;
  await wait(400); if (!alive(rid)) return;

  clearInput();
  addMessage('user', 'Fasse diese Seite zusammen');
  await wait(400); if (!alive(rid)) return;

  const thinking = addMessage('bot', thinkingDots(), 'streaming');
  await wait(2000); if (!alive(rid)) return;

  thinking.classList.remove('streaming');
  setHTML(thinking, 'Die Seite beschreibt die <strong>Kernbereiche</strong> und <strong>Leistungen</strong> des Unternehmens. Die Schwerpunkte umfassen mehrere Fachgebiete mit einem breiten Portfolio an Dienstleistungen.' +
    '<div class="cit"><div class="cit-label">📎 Quellen</div><ul><li><a>/about/overview</a></li><li><a>/services</a></li></ul></div>');
  await wait(4000);
}

/* ── Scene 3: Plus menu showcase ── */
async function scenePlusMenu(rid) {
  showPlusMenu();
  await wait(3500); if (!alive(rid)) return;
  hidePlusMenu();
  await wait(400);
}

/* ── Scene 4: Translation workflow ── */
async function sceneTranslation(rid) {
  clearMessages();
  showPlusMenu();
  await wait(800); if (!alive(rid)) return;
  hidePlusMenu();
  await wait(300); if (!alive(rid)) return;

  const ask = addMessage('bot', 'Was soll übersetzt werden?');
  await wait(400); if (!alive(rid)) return;

  const acts = createEl('div');
  acts.className = 'wiz-acts';
  setHTML(acts, '<button class="wiz-btn">Nur diese Seite</button><button class="wiz-btn">Mit Unterseiten</button><button class="wiz-btn ghost">Abbrechen</button>');
  ask.appendChild(acts);
  requestAnimationFrame(() => acts.classList.add('vis'));
  await wait(2000); if (!alive(rid)) return;

  addMessage('user', 'Nur diese Seite');
  acts.classList.remove('vis');
  await wait(500); if (!alive(rid)) return;

  const langAsk = addMessage('bot', 'In welche Sprache übersetzen?');
  await wait(300); if (!alive(rid)) return;
  const langActs = createEl('div');
  langActs.className = 'wiz-acts';
  setHTML(langActs, '<button class="wiz-btn primary">English</button><button class="wiz-btn">Français</button><button class="wiz-btn">Español</button><button class="wiz-btn ghost">Abbrechen</button>');
  langAsk.appendChild(langActs);
  requestAnimationFrame(() => langActs.classList.add('vis'));
  await wait(1800); if (!alive(rid)) return;

  addMessage('user', 'English');
  langActs.classList.remove('vis');
  await wait(400); if (!alive(rid)) return;

  const trans = addMessage('bot', 'Übersetze Seite nach English… ' + thinkingDots(), 'streaming');
  $('#transText').textContent = 'Übersetze nach English…';
  $('#transOverlay').classList.add('visible');
  await wait(2500); if (!alive(rid)) return;

  setCMS(cmsEN);
  setLang('en');
  $('#transOverlay').classList.remove('visible');
  await wait(300); if (!alive(rid)) return;

  flashElement($('#cmsTitle'));
  flashElement($('#cmsHeading'));
  flashElement($('#cmsText'));

  trans.classList.remove('streaming');
  setHTML(trans, '✓ Übersetzung nach <strong>English</strong> erfolgreich abgeschlossen.');
  trans.className = 'msg bot success vis';
  await wait(3000);
}

/* ── Scene 5: Text optimization with comparison ── */
async function sceneTextOptimize(rid) {
  clearMessages();

  /* Simulate cursor selecting text on the page */
  const textEl = $('#cmsText');
  const rect = textEl.getBoundingClientRect();
  showCursor(rect.left + 10, rect.top + 10);
  await wait(500); if (!alive(rid)) return;

  selectText(textEl, 0, textEl.textContent.length);
  await wait(600); if (!alive(rid)) return;
  hideCursor();

  setContext('Ausgewählter Text', 'selection');
  await wait(500); if (!alive(rid)) return;

  await typeIntoInput('Kürze auf das Wesentliche', 30, rid);
  if (!alive(rid)) return;
  await wait(300); if (!alive(rid)) return;

  clearInput();
  addMessage('user', 'Kürze auf das Wesentliche');
  await wait(500); if (!alive(rid)) return;

  const cmp = addMessage('bot',
    '<div class="cmp">' +
    '<div class="lbl">Original</div>' +
    '<div class="orig">At vero eos et accusamus et iusto odio dignissimos ducimus qui blanditiis praesentium voluptatum deleniti atque corrupti quos dolores et quas molestias.</div>' +
    '<div class="divider"></div>' +
    '<div class="lbl">Ergebnis</div>' +
    thinkingDots() +
    '</div>', 'streaming');
  await wait(2200); if (!alive(rid)) return;

  cmp.classList.remove('streaming');
  setHTML(cmp.querySelector('.cmp'),
    '<div class="lbl">Original</div>' +
    '<div class="orig">At vero eos et accusamus et iusto odio dignissimos ducimus qui blanditiis praesentium voluptatum deleniti atque corrupti quos dolores et quas molestias.</div>' +
    '<div class="divider"></div>' +
    '<div class="lbl">Ergebnis</div>' +
    '<div class="res">Dignissimos ducimus qui blanditiis — praesentium voluptatum deleniti.</div>');
  await wait(400); if (!alive(rid)) return;

  const applyActs = createEl('div');
  applyActs.className = 'wiz-acts';
  setHTML(applyActs, '<button class="wiz-btn primary">Anwenden</button><button class="wiz-btn">Nochmals</button><button class="wiz-btn">Bearbeiten</button><button class="wiz-btn ghost">Abbrechen</button>');
  cmp.appendChild(applyActs);
  requestAnimationFrame(() => applyActs.classList.add('vis'));
  await wait(2500); if (!alive(rid)) return;

  applyActs.classList.remove('vis');
  await wait(300); if (!alive(rid)) return;

  const applyMsg = addMessage('bot', 'Wende Änderungen an… ' + thinkingDots(), 'streaming');
  await wait(1000); if (!alive(rid)) return;

  clearSelection(textEl);
  textEl.textContent = "Dignissimos ducimus qui blanditiis — praesentium voluptatum deleniti.";
  flashElement(textEl);

  applyMsg.classList.remove('streaming');
  setHTML(applyMsg, '✓ Text wurde erfolgreich auf der Seite ersetzt.');
  applyMsg.className = 'msg bot success vis';
  clearContext();
  await wait(2500);
}

/* ── Scene 6: Edit mode ── */
async function sceneEditMode(rid) {
  clearMessages();

  /* Open plus menu and activate edit mode */
  showPlusMenu();
  await wait(800); if (!alive(rid)) return;
  $('#pmEdit').classList.add('active-item');
  $('#pmEdit').querySelector('span').textContent = 'Bearbeiten (aktiv)';
  await wait(600); if (!alive(rid)) return;
  hidePlusMenu();

  setContext('Bearbeiten-Modus', 'edit');
  await wait(500); if (!alive(rid)) return;

  await typeIntoInput('Modernisiere die Überschrift', 30, rid);
  if (!alive(rid)) return;
  await wait(300); if (!alive(rid)) return;

  clearInput();
  addMessage('user', 'Modernisiere die Überschrift');
  await wait(500); if (!alive(rid)) return;

  const editMsg = addMessage('bot', 'Bereite Seiten-Daten vor… ' + thinkingDots(), 'streaming');
  await wait(1200); if (!alive(rid)) return;
  setHTML(editMsg, 'Sende an Bearbeiten-Backend… ' + thinkingDots());
  await wait(1500); if (!alive(rid)) return;

  $('#cmsTitle').textContent = 'Amet Consectetur Adipiscing Elit Vivamus';
  flashElement($('#cmsTitle'));

  editMsg.classList.remove('streaming');
  setHTML(editMsg, '✓ Überschrift erfolgreich aktualisiert.');
  editMsg.className = 'msg bot success vis';
  await wait(2500);
}

/* ── Scene 7: Layout agent ── */
async function sceneLayoutAgent(rid) {
  clearMessages();
  clearContext();
  $('#pmEdit').classList.remove('active-item');
  $('#pmEdit').querySelector('span').textContent = 'Bearbeiten';

  setContext('Bearbeiten-Modus', 'edit');
  await wait(300); if (!alive(rid)) return;

  await typeIntoInput('Strukturiere die Seite neu', 30, rid);
  if (!alive(rid)) return;
  await wait(300); if (!alive(rid)) return;

  clearInput();
  addMessage('user', 'Strukturiere die Seite neu mit einem modernen Layout');
  await wait(500); if (!alive(rid)) return;

  const layoutMsg = addMessage('bot',
    '<strong>Layout-Agent</strong> gestartet…' +
    '<div class="layout-steps">' +
    '<div class="layout-step active" id="ls1"><div class="step-icon"><div class="step-spinner"></div></div><span>Analysiere aktuelle Seitenstruktur…</span></div>' +
    '<div class="layout-step" id="ls2"><div class="step-icon">○</div><span>Generiere neues Layout</span></div>' +
    '<div class="layout-step" id="ls3"><div class="step-icon">○</div><span>Wende Änderungen an</span></div>' +
    '</div>', 'streaming');
  await wait(2000); if (!alive(rid)) return;

  /* Step 1 done */
  const ls1 = layoutMsg.querySelector('#ls1');
  ls1.className = 'layout-step done';
  ls1.querySelector('.step-icon').textContent = '✓';
  const ls2 = layoutMsg.querySelector('#ls2');
  ls2.className = 'layout-step active';
  setHTML(ls2.querySelector('.step-icon'), '');
  var sp2 = createEl('div'); sp2.className = 'step-spinner'; ls2.querySelector('.step-icon').appendChild(sp2);
  await wait(2000); if (!alive(rid)) return;

  /* Step 2 done */
  ls2.className = 'layout-step done';
  ls2.querySelector('.step-icon').textContent = '✓';
  const ls3 = layoutMsg.querySelector('#ls3');
  ls3.className = 'layout-step active';
  setHTML(ls3.querySelector('.step-icon'), '');
  var sp3 = createEl('div'); sp3.className = 'step-spinner'; ls3.querySelector('.step-icon').appendChild(sp3);
  await wait(1500); if (!alive(rid)) return;

  /* Apply layout changes to page */
  $('#cmsTitle').textContent = 'Amet Consectetur Adipiscing Elit Vivamus';
  $('#cmsDesc').textContent = 'Nemo enim ipsam voluptatem quia voluptas sit aspernatur aut odit aut fugit.';
  flashElement($('#cmsTitle'));
  flashElement($('#cmsDesc'));
  flashElement($('#cmsHeading'));

  ls3.className = 'layout-step done';
  ls3.querySelector('.step-icon').textContent = '✓';
  layoutMsg.classList.remove('streaming');

  await wait(400); if (!alive(rid)) return;
  const doneMsg = addMessage('bot', '✓ Seitenlayout erfolgreich aktualisiert. 3 Blöcke wurden neu angeordnet.');
  doneMsg.className = 'msg bot success vis';
  await wait(3000);
}

/* ── Scene 8: Prompt picker ── */
async function scenePromptPicker(rid) {
  clearMessages();
  clearContext();
  showPlusMenu();
  await wait(600); if (!alive(rid)) return;
  hidePlusMenu();
  await wait(300); if (!alive(rid)) return;

  showPromptPicker();
  await wait(4000); if (!alive(rid)) return;
  hidePromptPicker();
  await wait(400);
}

/* ── Scene 9: History ── */
async function sceneHistory(rid) {
  openDrawer('#historyDrawer');
  await wait(3500); if (!alive(rid)) return;
  closeDrawer('#historyDrawer');
  await wait(400);
}

/* ── Scene: Header Menu ── */
async function sceneHeaderMenu(rid) {
  clearMessages();
  showHeaderMenu();
  await wait(3500); if (!alive(rid)) return;
  hideHeaderMenu();
  await wait(400);
}

/* ── Scene: Settings ── */
async function sceneSettings(rid) {
  openDrawer('#settingsDrawer');
  await wait(4000); if (!alive(rid)) return;
  closeDrawer('#settingsDrawer');
  await wait(400);
}

/* ── Scene: Glossary ── */
async function sceneGlossary(rid) {
  openDrawer('#glossaryDrawer');
  await wait(3500); if (!alive(rid)) return;
  closeDrawer('#glossaryDrawer');
  await wait(400);
}

/* ── Scene: Tag Mappings ── */
async function sceneTagMappings(rid) {
  openDrawer('#tagDrawer');
  await wait(3500); if (!alive(rid)) return;
  closeDrawer('#tagDrawer');
  await wait(400);
}

/* ── Scene: Prompts Management ── */
async function scenePromptsPanel(rid) {
  openDrawer('#promptsDrawer');
  await wait(4000); if (!alive(rid)) return;
  closeDrawer('#promptsDrawer');
  await wait(400);
}

/* ── Scene: Permissions ── */
async function scenePermissions(rid) {
  openDrawer('#permDrawer');
  await wait(3500); if (!alive(rid)) return;
  closeDrawer('#permDrawer');
  await wait(400);
}

/* ── Scene: Translation sync ── */
async function sceneSync(rid) {
  clearMessages();
  clearContext();
  $('#pmEdit').classList.remove('active-item');
  $('#pmEdit').querySelector('span').textContent = 'Bearbeiten';

  addMessage('bot',
    '<div class="sync-card">' +
    '<div class="sync-card-title">Veraltete Übersetzungen</div>' +
    '<div class="sec-hint" style="margin:0 0 6px">Folgende Übersetzungen sind nicht mehr aktuell:</div>' +
    '<div class="sync-item"><span class="sync-dot"></span><span>/de/about/team</span></div>' +
    '<div class="sync-item"><span class="sync-dot"></span><span>/de/services/overview</span></div>' +
    '<div style="margin-top:8px"><button class="btn btn-p btn-s">Synchronisieren</button></div>' +
    '</div>');
  await wait(3500);
}

/* ── Scene 11: Close ── */
async function sceneClose(rid) {
  clearMessages();
  clearContext();
  botArea.classList.remove('show-panel');
  botArea.classList.add('show-launcher', 'launcher-pulse');
  await wait(2500); if (!alive(rid)) return;
  botArea.classList.remove('show-launcher', 'launcher-pulse');
  await wait(1500);
}

/* ════════════════════════════════════════════
   TIMELINE UI
   ════════════════════════════════════════════ */
const tlTrack = $('#tlTrack');
const tlLabel = $('#tlLabel');
const tlPlay  = $('#tlPlay');

/* Build track dots */
scenes.forEach((s, i) => {
  const dot = createEl('div');
  dot.className = 'tl-dot';
  dot.title = s.name;
  dot.addEventListener('click', () => jumpTo(i));
  tlTrack.appendChild(dot);
});

function updateTimeline(idx) {
  curScene = idx;
  const dots = tlTrack.querySelectorAll('.tl-dot');
  dots.forEach((d, i) => {
    d.classList.remove('active', 'done');
    if (i < idx) d.classList.add('done');
    if (i === idx) d.classList.add('active');
  });
  tlLabel.textContent = scenes[idx].name;
}

/* ════════════════════════════════════════════
   PLAYBACK ENGINE
   ════════════════════════════════════════════ */
function prepareState(idx) {
  resetAll();
  /* Panel is visible from scene 1 onwards */
  if (idx >= 1) {
    botArea.classList.add('show-launcher', 'show-panel');
  }
  /* After translation (scenes 4+), CMS is in translated state until close */
  if (idx >= 4 && idx <= scenes.length - 2) {
    setCMS(cmsEN);
    setLang('en');
  }
  /* Edit mode active in scenes 6-7 */
  if (idx === 6 || idx === 7) {
    $('#pmEdit').classList.add('active-item');
    $('#pmEdit').querySelector('span').textContent = 'Bearbeiten (aktiv)';
  }
}

async function playFrom(startIdx) {
  const rid = ++runId;
  paused = false;
  updatePlayBtn();

  for (let i = startIdx; i < scenes.length; i++) {
    if (!alive(rid)) return;
    prepareState(i);
    clearMessages();
    clearContext();
    clearInput();
    hideCursor();
    if (i >= 1) botArea.classList.add('show-launcher', 'show-panel');
    updateTimeline(i);
    await scenes[i].fn(rid);
    if (!alive(rid)) return;
  }

  /* Loop */
  await wait(1000);
  if (!alive(rid)) return;
  playFrom(0);
}

function jumpTo(idx) {
  runId++;
  paused = false;
  updatePlayBtn();
  prepareState(idx);
  clearMessages();
  clearContext();
  clearInput();
  hideCursor();
  if (idx >= 1) botArea.classList.add('show-launcher', 'show-panel');
  playFrom(idx);
}

/* Play / Pause */
function togglePause() {
  paused = !paused;
  updatePlayBtn();
  if (!paused && _resolve) { const r = _resolve; _resolve = null; r(); }
}
function updatePlayBtn() {
  if (paused) {
    setHTML(tlPlay, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>');
    tlPlay.title = 'Abspielen';
  } else {
    setHTML(tlPlay, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor"><path d="M6 19h4V5H6zm8-14v14h4V5z"/></svg>');
    tlPlay.title = 'Pause';
  }
}

/* Controls */
$('#tlPrev').addEventListener('click', () => jumpTo(Math.max(0, curScene - 1)));
$('#tlNext').addEventListener('click', () => jumpTo(Math.min(scenes.length - 1, curScene + 1)));
tlPlay.addEventListener('click', togglePause);

/* ── Start ── */
updatePlayBtn();
playFrom(0);

